/* SideScroll 1.1.5 — Atlas-backed Parts preview (no second editor/panel).
 * The normal Parts list and transform tools own inventory editing. Part IDs
 * reference source geometry; the source PNG and vertices remain in Atlas.
 * Rig/Skin weights are NOT generated by this rigid rest preview.
 */
(() => {
  'use strict';
  const core=window.AnimLabCore;
  if(!core)return;
  const state=()=>core.getState();
  const atlas=()=>window.AnimLabAtlasInspect;
  const clone=o=>JSON.parse(JSON.stringify(o));
  const getInventory=()=>state()?.setup?.artLayout?.assembly;
  function drawMesh(args,part,mesh,image,selected){
    const {ctx,view,project}=args,verts=mesh?.vertices||[],tris=mesh?.triangles||[];
    if(!verts.length||!tris.length)return;
    const imageWidth=image?.naturalWidth||image?.width||atlas()?.getDocument?.()?.atlas?.width||1;
    const xs=verts.map(v=>v.x),ys=verts.map(v=>v.y);
    const cx=(Math.min(...xs)+Math.max(...xs))/2,ymax=Math.max(...ys);
    const ppu=.95/imageWidth,c=Math.cos(part.rotation||0),s=Math.sin(part.rotation||0);
    const ox=part.pivotX||0,oy=part.pivotY||0;
    const transform=(x,y)=>{
      const px=(x-cx)*ppu,py=(ymax-y)*ppu;
      return project({
        x:part.x+ox+c*(px-ox)*part.scaleX-s*(py-oy)*part.scaleY,
        y:part.y+oy+s*(px-ox)*part.scaleX+c*(py-oy)*part.scaleY
      },view);
    };
    const points=verts.map(v=>transform(v.x,v.y));
    ctx.save();ctx.beginPath();let count=0;
    for(const tri of tris){
      if(!Array.isArray(tri)||tri.length<3)continue;
      const a=points[tri[0]],b=points[tri[1]],c=points[tri[2]];
      if(!a||!b||!c)continue;
      ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.lineTo(c.x,c.y);ctx.closePath();count++;
    }
    if(!count){ctx.restore();return;}
    if(image&&(image.naturalWidth||image.width)){
      ctx.clip();
      const p0=transform(0,0),px=transform(1,0),py=transform(0,1);
      ctx.transform(px.x-p0.x,px.y-p0.y,py.x-p0.x,py.y-p0.y,p0.x,p0.y);
      ctx.drawImage(image,0,0);
      ctx.restore();
    }else{
      ctx.strokeStyle='rgba(244,167,112,.7)';ctx.lineWidth=1;ctx.stroke();ctx.restore();
    }
    if(selected){
      ctx.save();ctx.beginPath();
      for(const tri of tris){const a=points[tri[0]],b=points[tri[1]],c=points[tri[2]];
        if(!a||!b||!c)continue;
        ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.lineTo(c.x,c.y);ctx.closePath();
      }
      ctx.strokeStyle='rgba(241,191,100,.55)';ctx.lineWidth=.85;ctx.stroke();ctx.restore();
    }
  }
  core.registerArtRenderer?.('atlas-part-assembly',args=>{
    const s=state(),group=getInventory();
    const preview=s.mode==='setup'&&['art','rig'].includes(s.setupTool);
    if(!group?.enabled||!preview)return false;
    const atlasDoc=atlas()?.getDocument?.();
    const sameChar=atlas()?.getCharacterId?.()===s.characterId;
    const meshes=new Map(sameChar?(atlasDoc?.meshes||[]).map(m=>[m.id,m]):[]);
    const importedImage=sameChar?atlas()?.getImage?.():null;
    const legacy=window.AnimLabLegacyAtlas?.getSnapshot?.()||null;
    const builtin=new Map((legacy?.meshes||[]).map(m=>[`atlas-builtin-${m.id}`,m]));
    const display=window.AnimLabPartLayoutDisplay;
    const chosen=display?.getSelected?.()||null;
    const solo=display?.getSolo?.()||null;
    for(const part of group.instances||[]){
      if(display?.isHidden?.(part.id)||(solo&&solo!==part.id))continue;
      const original=builtin.get(part.meshId);
      const mesh=meshes.get(part.meshId)||original;
      if(mesh)drawMesh(args,part,mesh,original?legacy?.image:importedImage,
        s.setupTool==='art'&&part.id===chosen);
    }
    return true; // Single inventory; never display the six originals behind it.
  });
  window.AnimLabPartAssemblyInspect=Object.freeze({
    getInventory:()=>clone(getInventory()||{}),getSelectedId:()=>window.AnimLabPartLayoutDisplay?.getSelected?.()||null
  });
})();
